from datetime import datetime, timedelta
from functools import partial
from funcy import cache, reraise, SkipMemoization

calls = []
@cache(60, key_func=lambda x: x.lower())
def cached(x):
    calls.append(x)
    return len(x)
assert cached.memory == {}
assert cached.skip is SkipMemoization
assert cached('ABC') == cached('abc') == 3
assert calls == ['ABC']
assert cached.memory['abc'][0] == 3
cached.memory['abc'] = (99, datetime.now())
assert cached('abc') == 99
cached.memory['abc'] = (99, datetime.now() - timedelta(seconds=61))
assert cached('abc') == 3
cached.invalidate('ABC')
assert cached.memory == {}
cached('abc')
cached.invalidate_all()
assert cached.memory == {}

class CallableError(Exception):
    def __call__(self, error):
        raise AssertionError('Exception instances must not be called')

def verify(into, expected, args):
    original = ValueError('original')
    try:
        with reraise(ValueError, into):
            raise original
    except expected as transformed:
        assert transformed.args == args
        assert transformed.__cause__ is original
        if isinstance(into, BaseException):
            assert transformed is into
    else:
        raise AssertionError('No exception raised')

verify(RuntimeError, RuntimeError, ())
verify(RuntimeError('fixed'), RuntimeError, ('fixed',))
verify(CallableError('fixed'), CallableError, ('fixed',))
verify(lambda e: RuntimeError('changed ' + str(e)), RuntimeError, ('changed original',))
verify(partial(lambda prefix, e: RuntimeError(prefix + str(e)), 'partial '),
       RuntimeError, ('partial original',))

seen = []
@reraise(ValueError, lambda e: (seen.append(e), RuntimeError(str(e)))[1])
def decorated(value):
    if value:
        raise ValueError(value)
    return 'ok'
assert decorated(None) == 'ok'
assert not seen
for value in ['first', 'second']:
    try:
        decorated(value)
    except RuntimeError as e:
        assert str(e) == value
        assert e.__cause__ is seen[-1]
assert len(seen) == 2
try:
    with reraise(ValueError, lambda e: seen.append(e)):
        raise TypeError('unmatched')
except TypeError:
    pass
assert len(seen) == 2
print('Targeted R2/R3 checks passed')
